sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;

    c.backToAssessments = function() {

        $window.location.href =
            '?id=campus360_assessments';

    };


	c.backToDashboard = function() {

    $window.location.href =
        '?id=campus360_recruiter_dashboard_new';

};

};

sp_widget.css:
.c360-assessment-view {
  min-height: 100vh;
  background: #f6f8fc;
  padding: 42px 6%;
  color: #10184d;
}

.c360-assessment-container {
  max-width: 1050px;
  margin: 0 auto;
}

/* HEADER */

.c360-page-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 28px;
}

.c360-eyebrow {
  color: #5548e8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 7px;
}

.c360-page-header h1 {
  margin: 0;
  font-size: 27px;
  font-weight: 600;
}

.c360-page-header p {
  margin: 7px 0 0;
  color: #73799b;
  font-size: 12px;
}

.c360-back {
  border: none;
  background: transparent;
  color: #5548e8;
  font-size: 11px;
  font-weight: 500;
  text-decoration: none;
  margin-top: 5px;
  padding: 0;
  cursor: pointer;
}

.c360-back:hover {
  text-decoration: underline;
}

.c360-secondary-button {
  border: 1px solid #d8d9eb;
  background: #ffffff;
  color: #5550df;
  padding: 9px 16px;
  border-radius: 7px;
  font-size: 11px;
  text-decoration: none;
  cursor: pointer;
}

.c360-secondary-button:hover {
  background: #f7f6ff;
}


/* MAIN CARD */

.c360-details-card {
  background: #ffffff;
  border: 1px solid #dedff0;
  border-radius: 12px;
  padding: 28px;
  box-shadow: 0 3px 12px rgba(40, 45, 90, 0.04);
}


/* DETAILS HEADER */

.c360-details-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding-bottom: 22px;
  border-bottom: 1px solid #ececf4;
}

.c360-details-header h2 {
  margin: 0;
  color: #11184f;
  font-size: 21px;
  font-weight: 600;
}

.c360-assessment-id {
  display: block;
  margin-top: 6px;
  color: #8b8faa;
  font-size: 10px;
}


/* STATUS */

.c360-status {
  padding: 6px 12px;
  border-radius: 7px;
  font-size: 10px;
  font-weight: 600;
}

.status-published {
  background: #dcf7ec;
  color: #16845c;
}

.status-draft {
  background: #f1f1f5;
  color: #6d7087;
}

.status-pending {
  background: #fff1d5;
  color: #bd7900;
}


/* GRID */

.c360-details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  margin-top: 10px;
}

.c360-detail-item {
  padding: 18px 12px 18px 0;
  border-bottom: 1px solid #eeeeF5;
}

.c360-detail-item label {
  display: block;
  color: #8589a5;
  font-size: 10px;
  font-weight: 600;
  margin-bottom: 7px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.c360-detail-item strong {
  color: #171d50;
  font-size: 12px;
  font-weight: 500;
}


/* INSTRUCTIONS */

.c360-instructions {
  margin-top: 25px;
}

.c360-instructions > label {
  display: block;
  color: #8589a5;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.c360-instructions-box {
  background: #f8f8fc;
  border: 1px solid #e7e7f0;
  border-radius: 8px;
  min-height: 80px;
  padding: 14px;
  color: #555b7d;
  font-size: 12px;
  line-height: 1.6;
}


/* ACTIONS */

.c360-details-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 25px;
  padding-top: 18px;
  border-top: 1px solid #eeeeF5;
}

.c360-secondary-button {
  border: 1px solid #d8d9eb;
  background: #ffffff;
  color: #5550df;
  padding: 9px 16px;
  border-radius: 7px;
  font-size: 11px;
  text-decoration: none;
}

.c360-secondary-button:hover {
  background: #f7f6ff;
}


/* LOADING */

.c360-loading {
  background: #ffffff;
  border: 1px solid #dedff0;
  border-radius: 12px;
  padding: 50px;
  text-align: center;
  color: #777b99;
  font-size: 12px;
}


/* NOT FOUND */

.c360-not-found {
  background: #ffffff;
  border: 1px solid #dedff0;
  border-radius: 12px;
  padding: 50px;
  text-align: center;
}

.c360-not-found h2 {
  margin: 0 0 8px;
  font-size: 18px;
}

.c360-not-found p {
  color: #777b99;
  font-size: 12px;
}

.c360-not-found a {
  color: #5548e8;
  font-size: 11px;
}


/* MOBILE */

@media (max-width: 700px) {

  .c360-assessment-view {
    padding: 25px 18px;
  }

  .c360-page-header {
    flex-direction: column;
    gap: 15px;
  }

  .c360-details-grid {
    grid-template-columns: 1fr;
  }

}

sp_widget.script:
(function() {

    data.loading = true;
    data.assessment = null;

    var sysId = $sp.getParameter('sys_id');

    if (!sysId) {
        data.loading = false;
        return;
    }

    var gr = new GlideRecord('x_snc_campus360_student_assessment');

    if (!gr.get(sysId)) {
        data.loading = false;
        return;
    }

    data.assessment = {

        sys_id: gr.getUniqueValue(),

        name: gr.getValue('assessment_name'),

        assessment_id: gr.getValue('assessment_id'),

        opportunity: gr.getDisplayValue('opportunity'),

        type: gr.getValue('assessment_type'),

        date: gr.getDisplayValue('assessment_date'),

        duration: gr.getValue('duration'),

        maximum_score: gr.getValue('maximum_score'),

        status: gr.getValue('status'),

        instructions: gr.getValue('instructions'),

        created_by: gr.getDisplayValue('sys_created_by')

    };

    data.loading = false;

})();
